var RECIPES=[{"id":"biryani","country":"Pakistan","name":"Chicken Biryani","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":60,"diff":"Medium","servings":"4 people","img":"assets/hero-49347f9b.webp","videos":{"en":"a6k4gpStnX0","ru":"ZeGEe2sKvHQ","hi":"HLLFfmH_rsg","es":"6wHV6tBKnjI","fr":"4l_INHwgeTY","ar":"lfgY7JVpkN8","pt":"usNzvglYMYA","rus":"ApkU_NqpT_c","zh":"k7ogYWfE6Zs","ja":"TtNBr6ZnLpE","de":"96iuaCOSwEg","tr":"IIHiUDS9_f8","bn":"AVc1vL_6QUc"},"shape":"tall","alt":"A plate of chicken biryani with saffron rice and fresh coriander","desc":"Karachi-style biryani, spiced chicken, fragrant basmati and the dum aroma that fills the whole house.","intro":"Biryani is not just food, it is a feast. Marinate the chicken in yoghurt and spices, boil the rice halfway, then put it on dum, masala below, rice on top, and the colour in between that makes every bite special.","ing":["Chicken 750g, yoghurt 1 cup","Basmati rice 3 cups, soaked","Biryani masala 3 tbsp, ginger-garlic paste 2 tbsp","Onions 3, browned","Tomatoes 2, green chillies 4","Fresh coriander, mint, lemon","Saffron / food colour, ghee 3 tbsp"],"steps":["Mix yoghurt, masala and ginger-garlic into the chicken and marinate for 30 minutes.","Boil the rice with salt and whole spices until 70% cooked, then drain.","Brown the onions, add tomatoes and the marinated chicken, and fry the masala well.","Layer masala first, then rice, and top with onions, coriander and saffron.","Cover and cook on low heat on dum for 20 minutes, then mix gently and serve."],"tip":"Do not over-boil the rice, it will finish cooking on dum. Put a cloth over the lid on dum so the steam does not escape."},{"id":"nihari","country":"Pakistan","name":"Beef Nihari","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":90,"diff":"Hard","servings":"5 people","img":"assets/trend-card-1-20dab29d.webp","video":"Ttifj2d5Aeo","videos":{"en":"Ttifj2d5Aeo","ru":"caDmv7OgvDo","hi":"y4weMzw_pRk","es":"jlExGSGRh5g","fr":"m0gzVcrC2n8","ar":"Xdw4ZkYwfDI","pt":"lyV2RmM8GmU","rus":"KbHSZhTaZ5Q","zh":"ZD8_Dhmx4xo","ja":"Q7Y-RxXQjnk","de":"_poiVshOkzw","tr":"ReekW3qCqMU","bn":"VZg4m8rbvVg"},"shape":"tall","alt":"A bowl of beef nihari with deep masala and ginger","desc":"Slow-cooked nihari, tender meat, deep masala and the gravy that finishes with naan.","intro":"Nihari is not fast food, it is food of patience. Cook the meat on low heat for hours, until it falls off the bone and the gravy takes on its deep colour and flavour.","ing":["Beef (shank) 1 kg","Nihari masala 4 tbsp, flour 3 tbsp","Ginger-garlic paste 2 tbsp, onion 1","Ghee / oil ½ cup","Ginger, green chilli, lemon, for garnish","Fresh coriander"],"steps":["Lightly brown the onion in ghee, add ginger-garlic and fry.","Add the meat and nihari masala and fry well.","Add water, cover, and cook on low heat for 2 hours.","Dissolve flour in water, add it, and cook until the gravy thickens.","Serve with naan, garnished with ginger, green chilli, lemon and coriander."],"tip":"Do not keep the gravy thin, nihari is known for its thick, glossy gravy. Add the flour slowly so no lumps form."},{"id":"karahi","country":"Pakistan","name":"Chicken Karahi","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":40,"diff":"Easy","servings":"4 people","img":"assets/chicken-karahi-72a3c2f2.webp","videos":{"en":"31ZEPj6qgZo","ru":"KInsyNWiyb4","hi":"Pf1aHakuogg","es":"iJ-PU15qqF0","fr":"cDrI9MgBsKA","ar":"SnacSWi9gBY","pt":"trQJm95pIxE","rus":"MgZF7YyMoBs","zh":"NJniWRtrcik","ja":"2bFIaEL2mx8","de":"Los0i1g2bik","tr":"WLxPEk76izk","bn":"LKAmurfdzIg"},"shape":"wide","alt":"Chicken karahi in a kadhai with tomatoes and green chillies","desc":"Dhaba-style karahi, fresh tomatoes, ginger and green chillies, exactly the taste you get at a karahi dhaba.","intro":"The secret of karahi is fresh tomatoes and high heat. No onion is needed, the tomato water itself becomes the masala, and ginger and green chillies at the end complete it.","ing":["Chicken 750g, tomatoes 4 large","Ginger-garlic paste 1 tbsp","Green chillies 4, ginger julienne","Ghee / oil ½ cup","Salt, crushed red chilli, garam masala","Fresh coriander"],"steps":["Heat ghee in a kadhai and fry the chicken on high heat.","Add ginger-garlic, then tomatoes, and cover.","When the tomatoes soften, mash them with a spoon and fry the masala.","When the oil rises to the top, add green chillies, ginger and garam masala.","Give 5 minutes of dum, add coriander, and serve with roti or naan."],"tip":"Do not add water to karahi, the tomatoes' own water is enough. Keep the heat high so the chicken stays tender and the masala well fried."},{"id":"daal","country":"India","name":"Daal Fry (Tadka Daal)","cat":"desi","catLabel":"Desi Dishes","veg":"veg","time":35,"diff":"Easy","servings":"4 people","img":"assets/daal-fry-tadka-daal-699cd89e.webp","shape":"tall","alt":"A bowl of tadka daal with red chilli and cumin tempering","desc":"Home-style daal with a cumin and red chilli tadka on top, perfect with rice or roti.","intro":"Daal is every home's daily food, but the tadka makes it special. Boil the daal until soft, then temper cumin, garlic and whole red chillies in ghee, the aroma alone is enough.","ing":["Masoor / moong daal 1½ cups","Turmeric ½ tsp, salt","Garlic 4 cloves, cumin 1 tsp","Whole red chillies 3, ghee 3 tbsp","Green chilli, fresh coriander, lemon"],"steps":["Wash the daal and boil with turmeric and water until soft.","Fry cumin and garlic in ghee until golden, add the red chillies.","Pour the tadka over the daal at once and cover for 2 minutes.","Add green chilli and coriander and mix.","Serve hot with rice or roti."],"tip":"Cover the daal as soon as you pour the tadka, this keeps the aroma inside the daal instead of letting it escape."},{"id":"chapli","country":"Pakistan","name":"Chapli Kabab","cat":"bbq","catLabel":"BBQ","veg":"nonveg","time":30,"diff":"Medium","servings":"4 people","img":"assets/chapli-kabab-23a29baa.webp","videos":{"en":"mv9tF5mN1Bk","ru":"spv0xat-Ogo","hi":"4Bm9MAEACWU","es":"JigVx5T72pw","fr":"BYQKWyk5PTQ","ar":"Jo2vYgEYFlQ","pt":"_-5b9Zqm9D4","rus":"cKHz2gQvt2g","zh":"S8ZCjPFO-JM","ja":"Y5JyZCYx-Uc","de":"u2yaPP3icS8","tr":"RHsFRrRuMUo","bn":"Rh-RVKXoFrY"},"shape":"wide","alt":"A plate of chapli kebabs with green chutney and salad","desc":"Peshawari chapli kebab, pomegranate seeds, tomato and the masala you feel in every bite.","intro":"Chapli kebab means flat, soft and spicy. Mix tomato, pomegranate seeds and whole spices into the mince, flatten it by hand, then fry both sides on a tawa.","ing":["Beef mince 500g","Tomato 1 finely chopped, onion 1","Pomegranate seeds 1 tbsp, crushed whole coriander","Green chillies 3, ginger, salt","Maize flour 2 tbsp","Oil for frying"],"steps":["Mix tomato, onion, spices and maize flour into the mince and rest for 20 minutes.","With wet hands, make flat kebabs and press a tomato piece in the centre.","Heat oil on a tawa and fry the kebabs on low heat.","When golden on both sides, remove them.","Serve with green chutney, onion and naan."],"tip":"Do not press the kebabs too much, turn them gently or they will break. Cold mince makes better kebabs."},{"id":"tikka","country":"Pakistan","name":"Chicken Tikka","cat":"bbq","catLabel":"BBQ","veg":"nonveg","time":45,"diff":"Easy","servings":"4 people","img":"assets/chicken-tikka-07347e22.webp","videos":{"en":"1tQ4kCSA66k","ru":"xDxs9BqlM8w","hi":"m4siRREwvAA","es":"cWocEvSPzTA","fr":"aci3XL8qzbc","ar":"YnrAwjGcvbk","pt":"Q5UlXjR3Nr4","rus":"UtbL88KdcwA","zh":"5_8FkLKEdw0","ja":"RwCLOOKuQlM","de":"Oa-MyBFczSI","tr":"sfXmFA6CqZ8","bn":"QG_PSAXSt2Q"},"shape":"tall","alt":"Chicken tikka pieces with spices and char aroma","desc":"Tandoori-style chicken tikka, marinated in yoghurt and spices, finished with lemon and chaat masala.","intro":"Good tikka comes from marination. Keep chicken in yoghurt, red chilli and garam masala for at least 1 hour, then grill on high heat, lightly charred outside, juicy inside.","ing":["Chicken (leg / boneless) 750g","Yoghurt ½ cup, red chilli 1 tbsp","Turmeric, garam masala, cumin powder","Ginger-garlic paste 1 tbsp, lemon 1","Oil / butter for brushing"],"steps":["Make a paste of yoghurt, all spices and ginger-garlic.","Score the chicken, coat it well with masala, and rest for 1 hour.","Grill on high heat, brushing with butter in between.","When golden and charred on both sides, remove.","Sprinkle lemon and chaat masala and serve."],"tip":"The longer the marination, the softer the tikka. If time is short, give it at least 30 minutes."},{"id":"halwapuri","country":"Pakistan","name":"Halwa Puri Nashta","cat":"nashta","catLabel":"Breakfast","veg":"veg","time":50,"diff":"Medium","servings":"4 people","img":"assets/halwa-puri-nashta-43dc5fe8.webp","videos":{"en":"yTGbGsFZg8Q","ru":"Td1UYcSSmbE","hi":"348Ccq2Bv9s","es":"g7oPPsPlRK0","fr":"9uRHYaKHNwo","ar":"36I6VmxYQGQ","pt":"A19CVQvJ1OQ","rus":"KaMxBL-Pwao","zh":"2zjF5Mv4Wsk","ja":"hGiZ9BAfg2s","de":"Ek6Mifk-BTw","tr":"15JBR6FjXoE","bn":"LEboQELi-KE"},"shape":"wide","alt":"Halwa puri breakfast, puffed puri, halwa and chickpeas","desc":"Sunday breakfast, puffed puri, soft semolina halwa and spiced chickpeas, just like Lahore.","intro":"Halwa puri is not breakfast, it is a tradition. Puffed puri, soft halwa and spiced chickpeas, the combination of all three is the soul of this breakfast.","ing":["Flour 2 cups, semolina 1 cup","Sugar 1 cup, ghee ½ cup","Chickpeas (boiled) 2 cups","Potato 1, onion, tomato","Garam masala, turmeric, red chilli","Cardamom, almonds for garnish"],"steps":["Knead the flour, roll small puris and deep-fry in hot oil until puffed.","Roast semolina in ghee, add sugar syrup and make halwa.","Cook chickpeas with masala, potato and tomato.","Add cardamom and almonds to the halwa.","Serve puri, halwa and chickpeas together."],"tip":"Do not use too much flour while rolling puri, or it will not puff. If the oil is well heated, the puri puffs at once."},{"id":"samosa","country":"India","name":"Punjabi Samosa","cat":"street","catLabel":"Street Food","veg":"veg","time":45,"diff":"Medium","servings":"6 people","img":"assets/punjabi-samosa-307fb89d.webp","videos":{"en":"AtUpMrfILW0","ru":"xYdOlbSqAN4","hi":"XYuZbpmxF2A","es":"uZqNpuPd2x8","fr":"v2pShTwy9VY","ar":"fyTHjioGeEA","pt":"hkPoukSOioY","rus":"Iu-Fs4IUE54","zh":"JnVVP--9F_s","ja":"KT2QlrQeVhE","de":"4D62lTb2EOQ","tr":"OlZuHJrPoKY","bn":"Vtp-0JePB74"},"shape":"wide","alt":"A plate of samosas with chutney","desc":"Crispy Punjabi samosa, spiced potato, green chutney and tea, the best evening pair.","intro":"A samosa lives in its crisp pastry and spiced potato. Knead the flour firm, mix garam masala and coriander into the potato, then fry on low heat, the pastry will be golden and crisp.","ing":["Flour 2 cups, carom seeds ½ tsp","Potatoes (boiled) 4, peas ½ cup","Ginger, green chilli, garam masala","Fresh coriander, pomegranate seeds","Oil for frying"],"steps":["Mix carom seeds and ghee into the flour, knead a firm dough, and rest for 20 minutes.","Mash the potatoes and mix in spices, peas and coriander.","Roll the dough, shape samosas and fill with the mixture.","Seal the edges well and fry on low heat until golden.","Serve with green and tamarind chutney."],"tip":"Always fry samosas on low heat, on high heat the pastry will burn and the inside will stay raw."},{"id":"bunkebab","country":"Pakistan","name":"Bun Kebab","cat":"street","catLabel":"Street Food","veg":"nonveg","time":25,"diff":"Easy","servings":"4 people","img":"assets/bun-kebab-fca6f5e9.webp","videos":{"en":"7U6PEk1Mx_M","ru":"_sNEDLn_FvI","hi":"PdeTc8dIiTA","es":"8NLgSqEuRUc","fr":"xvNLzlklqZE","ar":"jEhVffen_gs","pt":"85RY3SIDhBc","rus":"LCBwfPIID2I","zh":"pJVqxh65Ivk","ja":"7tjqOWnxmJU","de":"U_MLxDnELlo","tr":"rhUTm67kXY8","bn":"d5Umsd6LG0g"},"shape":"square","alt":"Bun kebab, kebab, onion and chutney inside a bun","desc":"Karachi street-style bun kebab, shami kebab, tamarind chutney and onion, packed in a bun.","intro":"Bun kebab is Karachi's identity. Fry shami kebabs on a tawa, place them in a bun, add onion, tomato and tamarind chutney, every bite has the perfect balance of masala and chutney.","ing":["Shami kebabs 8, buns 4","Onion, tomato, green chutney","Tamarind chutney, yoghurt","Green chilli, fresh coriander","Butter for toasting the bun"],"steps":["Fry the shami kebabs in a little oil on both sides.","Butter the buns and lightly toast them on the tawa.","Spread chutney on the bun and place the kebab.","Add onion, tomato and green chilli.","Close the bun and serve hot."],"tip":"Do not over-toast the bun, lightly golden is enough, or it will become hard."},{"id":"gulabjamun","country":"India","name":"Gulab Jamun","cat":"meetha","catLabel":"Desserts","veg":"veg","time":40,"diff":"Medium","servings":"6 people","img":"assets/trend-card-2-009bdad8.webp","videos":{"en":"8U7omAUUqG8","ru":"ZmmQtyGiqWU","hi":"Y0VaRwnMIgs","es":"5kdJK92pJjI","fr":"2jWmZf88wp4","ar":"PK-5g7SCmeo","pt":"WLyT-yJCrWc","rus":"xmDOwJ0ME8A","zh":"B_-AArSbDK4","ja":"vEfgouGUcqI","de":"eZjSwgpJih8","tr":"9hEZjAOILxU","bn":"sj_MSCQ3N5c"},"shape":"tall","alt":"Gulab jamun in syrup with rose aroma","desc":"Soft gulab jamun, khoya, syrup and cardamom, the most-loved sweet for Eid and feasts.","intro":"Gulab jamun turn soft when the khoya is good and the syrup is lightly warm. Fry the jamuns on low heat, then put them in syrup for 1 hour, they will drink the syrup and swell.","ing":["Khoya 250g, flour 3 tbsp","Cardamom powder ½ tsp","Sugar 2 cups, water 2 cups","Rose water 1 tsp, 2 drops of lemon","Oil / ghee for frying"],"steps":["Mix khoya and flour into a soft dough and make small balls.","Make syrup from sugar and water, add cardamom and rose water.","Fry the jamuns on low heat until lightly golden.","Put the hot jamuns into the warm syrup.","Rest for 1 hour, then serve."],"tip":"The jamuns should have no cracks, grease your hands lightly with ghee while shaping the balls. The syrup should not be too hot, or the jamuns will harden."},{"id":"gajarhalwa","country":"India","name":"Gajar Ka Halwa","cat":"meetha","catLabel":"Desserts","veg":"veg","time":55,"diff":"Medium","servings":"5 people","img":"assets/gajar-ka-halwa-fc5f08bf.webp","videos":{"en":"CVaE76tT-1U","ru":"cpNu3H_40rY","hi":"wizd84RWb7o","es":"QOyLKv0VHDw","fr":"0rCtlfmvVTA","ar":"WRJx_pi9aw4","pt":"8DTJqlVDtWY","rus":"llYQMSQLUgA","zh":"gGot_BXyMh8","ja":"4cl0-sYknlM","de":"h2ahtV9CjfQ","tr":"lm8ktGbDXkE","bn":"TFxuoO__vkY"},"shape":"tall","alt":"Gajar ka halwa with khoya and almonds","desc":"Winter gajar ka halwa, red carrots, milk, khoya and ghee, just like home.","intro":"Gajar ka halwa needs patience. Cook the carrots in milk on low heat; when the milk dries, add ghee and sugar, and finish with khoya and almonds, the best winter aroma.","ing":["Red carrots 1 kg, grated","Milk 1 litre, sugar 1 cup","Ghee 4 tbsp, khoya 150g","Cardamom 4, almonds / pistachios"],"steps":["Put carrots and milk in a kadhai and cook on low heat.","When the milk dries, add ghee and fry.","Add sugar and cook until the halwa leaves the kadhai.","Mix in khoya and cardamom and cook for 5 minutes.","Add almonds and pistachios and serve."],"tip":"Grate the carrots finely, thick carrots take longer to cook and the halwa stays coarse."},{"id":"lassi","country":"India","name":"Mango Lassi","cat":"drinks","catLabel":"Drinks","veg":"veg","time":15,"diff":"Easy","servings":"3 people","img":"assets/mango-lassi-bb084ab7.webp","videos":{"en":"8n7XRXqyfZ0","ru":"2J2mSFW-t8c","hi":"s3w8bhPWQcE","es":"gQi4yC7X5Oc","fr":"4AxP0JVVi1s","ar":"U5N41RTi6vE","pt":"3D9NGTw7wl8","rus":"0d3TUPDOJ9g","zh":"1T8CuVO_3vI","ja":"oRjLjG8VSys","de":"2pQ6NubFbnw","tr":"DcDrjRckXfU","bn":"Iq4Yi0B-Q7k"},"shape":"tall","alt":"A glass of mango lassi with mango and mint","desc":"Chilled mango lassi, ripe mangoes, yoghurt and cardamom, the most soothing drink in summer.","intro":"Mango lassi is summer's answer. Take ripe, sweet mangoes, add cold yoghurt and cardamom aroma, 1 minute in the blender, and comfort in a glass.","ing":["Ripe mangoes 2, yoghurt 1½ cups","Milk ½ cup, sugar 2 tbsp (to taste)","Cardamom powder ¼ tsp","Ice cubes, mint for garnish"],"steps":["Peel the mangoes and cut into pieces.","Put mango, yoghurt, milk and sugar in a blender.","Add cardamom and ice and blend for 1 minute.","Pour into glasses and garnish with mint.","Serve chilled at once."],"tip":"The sweeter the mango, the less sugar you need. Do not make lassi in advance, freshly blended is best."},{"id":"pizza","name":"Margherita Pizza","cat":"world","catLabel":"World Food","country":"Italy","veg":"veg","time":75,"diff":"Medium","servings":"4 people","img":"assets/margherita-pizza-22ce327b.webp","videos":{"en":"GPn_absd5b8","ru":"CAoqkV4uOmM","hi":"kBZKJdYfd7k","es":"0vvLyH25m9A","fr":"5OVYwjYZktI","ar":"Rf_8mSSh4SQ","pt":"LW66CzyiHvk","rus":"SIU45MxcRGg","zh":"7lfBEizLP2A","ja":"bDxzMga31zI","de":"mWpdOn0Lmt8","tr":"oU1Ar-hjSkI","bn":"Bg0WQKoWdG8"},"shape":"tall","alt":"A margherita pizza with tomato sauce, melted mozzarella and fresh basil","desc":"From Italy, a classic Neapolitan pizza with tomato, fior di latte mozzarella and fresh basil.","intro":"Margherita pizza is proof that simple food can be extraordinary. It was made famous in Naples, where a hot oven, a thin crust, bright tomato sauce and good mozzarella do all the work. The colours are said to echo the Italian flag, red tomato, white mozzarella and green basil, and the flavour is clean and fresh rather than heavy. This version uses a dough that rests long enough to become light and chewy, a sauce that is barely cooked, and a very hot oven so the crust blisters in minutes. Take time with the dough and the heat, and the pizza will taste like a pizzeria pizza, even from a home oven.","ing":["Strong bread flour 500g, warm water 325ml","Instant yeast 7g, fine salt 10g, olive oil 2 tbsp","San Marzano tomatoes 400g, crushed","Fior di latte mozzarella 250g, torn","Fresh basil leaves 1 handful","Garlic 1 clove, olive oil and salt for the sauce","Semolina or flour for dusting"],"steps":["Mix the flour, water, yeast and salt, knead for 8 to 10 minutes until smooth, then rest the dough covered for 1 hour, or overnight in the fridge for better flavour.","Crush the tomatoes with garlic, a pinch of salt and 1 tbsp of olive oil. Do not cook the sauce, it cooks on the pizza.","Divide the dough into 4 balls, rest for 20 minutes, then stretch each one by hand from the centre out, leaving a thicker edge.","Heat the oven as hot as it will go, at least 250C, with a pizza stone or an upside down baking tray inside for 30 minutes.","Spread 3 to 4 tbsp of sauce on each base, leaving the edge clear, and scatter the torn mozzarella over the top."],"tip":"Do not overload the pizza. A thin layer of sauce and a modest amount of cheese let the crust cook through and stay crisp."},{"id":"carbonara","name":"Spaghetti Carbonara","cat":"world","catLabel":"World Food","country":"Italy","veg":"nonveg","time":25,"diff":"Easy","servings":"4 people","img":"assets/spaghetti-carbonara-50bc65b0.webp","videos":{"en":"LhbQ7bdXsXw","ru":"oAPq18l_fZc","hi":"aw4YLP_9wPE","es":"2PWUYr2sAY0","fr":"kS3nyQBQDU0","ar":"xl4F2rvhh0o","pt":"JE-s4DCDTFw","rus":"soNNe3NBsWE","zh":"Gq5Z0sCEjIs","ja":"9zBmYPvAOiE","de":"S4v21Az_PqU","tr":"dMo3K18BkKY","bn":"vtqLG5GqT6w"},"shape":"square","alt":"Spaghetti carbonara with pancetta, egg sauce and grated pecorino","desc":"From Italy, silky spaghetti carbonara made with eggs and pecorino, with no cream at all.","intro":"Real carbonara has no cream. It comes from Rome, and its sauce is made only from eggs, pecorino cheese, black pepper and the fat from guanciale or pancetta, mixed with hot pasta until it turns glossy and silky. The trick is heat control. The pan must be hot enough to cook the eggs gently into a sauce, but never so hot that they scramble. Work quickly, use pasta water to loosen the sauce, and serve at once. Once you learn the timing, this becomes one of the fastest and most comforting pasta dishes you can make, with only a handful of ingredients and a depth of flavour that tastes far more complex than it is.","ing":["Spaghetti 400g","Guanciale or pancetta 150g, diced","Egg yolks 4, plus 1 whole egg","Pecorino Romano 60g, finely grated","Black pepper 2 tsp, freshly cracked","Salt for the pasta water","Extra pecorino and pepper to serve"],"steps":["Boil the spaghetti in well salted water until just al dente, and keep 1 cup of the pasta water before draining.","Fry the guanciale or pancetta in a dry pan on medium heat for 6 to 8 minutes until crisp at the edges and the fat has melted out.","Whisk the yolks, whole egg, pecorino and most of the black pepper into a thick paste. Add a spoon of pasta water if it is too stiff.","Take the pan off the heat and let it cool for 1 minute, so the eggs will not scramble when they meet the pan.","Add the drained spaghetti to the pan and toss well in the rendered fat for 30 seconds."],"tip":"Take the pan off the heat before adding the eggs. Residual heat makes the sauce, direct heat makes scrambled eggs."},{"id":"sushi","name":"Sushi","cat":"world","catLabel":"World Food","country":"Japan","veg":"nonveg","time":50,"diff":"Medium","servings":"4 people","img":"assets/sushi-2508fc3b.webp","videos":{"en":"bcrnzvui6Cw","ru":"BAyH7vj5IgM","hi":"KtnXv8NBm4g","es":"Qr0Iz1Hm6WI","fr":"5ZEsPyN0gUI","ar":"yPJabifcraY","pt":"mNSW1VbcGC0","rus":"mzPE_gcPrvw","zh":"OXLK5Dkwqe8","ja":"_BmKR5EfwJ4","de":"KrRubWbw4zY","tr":"oGt0-iPxQLE","bn":"aqVp6OPPZ5c"},"shape":"tall","alt":"Salmon and cucumber sushi rolls with rice, nori and sesame seeds","desc":"From Japan, salmon and cucumber sushi rolls with seasoned rice, nori and a little wasabi.","intro":"Sushi is about rice first and fish second. In Japan, the rice is seasoned with vinegar, sugar and salt, fanned cool, and handled gently so every grain stays separate and glossy. This home version makes salmon and cucumber rolls, the kind that are easiest to learn, with nori on the outside, rice in the middle, and a neat line of filling. Use sushi grade salmon, keep your hands wet, and roll firmly but gently. The first roll may look uneven, and that is normal. By the third roll, the shape, the cut and the confidence all come together, and the result tastes fresh, clean and far better than shop bought sushi that has sat in a fridge.","ing":["Sushi rice 2 cups, uncooked","Rice vinegar 4 tbsp, sugar 2 tbsp, salt 1 tsp","Nori sheets 4","Sushi grade salmon 300g, cut into strips","Cucumber 1, cut into thin sticks","Mayonnaise 3 tbsp, sriracha 1 tsp, for spicy mayo","Soy sauce, pickled ginger and wasabi to serve","Sesame seeds 1 tbsp, optional"],"steps":["Rinse the rice until the water runs clear, cook it, then rest it covered for 10 minutes.","Warm the vinegar, sugar and salt until dissolved, fold it into the hot rice with a slicing motion, and fan the rice until it is just warm and glossy.","Lay a nori sheet shiny side down on a bamboo mat, wet your hands, and spread a thin even layer of rice, leaving 2cm bare at the far edge.","Spread a thin line of spicy mayo across the centre, add salmon and cucumber sticks in a neat row, and sprinkle with sesame seeds.","Lift the near edge of the mat and roll firmly away from you, tucking the filling in, and press gently to seal the bare edge with a little water."],"tip":"Keep a bowl of water nearby and wet your hands and knife often. Wet hands stop the rice sticking, and a wet blade cuts cleanly without squashing the roll."},{"id":"ramen","name":"Ramen","cat":"world","catLabel":"World Food","country":"Japan","veg":"nonveg","time":45,"diff":"Medium","servings":"4 people","img":"assets/ramen-e463426c.webp","videos":{"en":"mWFDKl2dcJQ","ru":"FEH60cUxhqA","hi":"td680CiO9jE","es":"QvYYqhlZEGQ","fr":"6TURngkWT7Q","ar":"GIEQmm41JE4","pt":"7EKK-PNdKh0","rus":"0iNHiXsRRec","zh":"zKj8wUrSEHU","ja":"x3BTNnmlt8Q","de":"PQt0BbiHyUQ","tr":"OYVoQ3t_HJ4","bn":"9-Mvk6kPLxk"},"shape":"tall","alt":"A bowl of chicken ramen with noodles, egg, chicken and spring onions","desc":"From Japan, chicken ramen with a rich broth, springy noodles, a soft egg and fresh toppings.","intro":"Ramen is comfort in a bowl, and a good home version does not need a broth that simmers all day. This chicken ramen builds flavour quickly, with garlic, ginger and spring onions fried in sesame oil, chicken stock enriched with soy and miso, and noodles cooked separately so the broth stays clear and the noodles stay springy. The egg is the finishing touch, soft in the middle and seasoned by the broth as you eat. Set out the toppings in small bowls and let everyone build their own bowl, hot broth last, so the noodles do not sit and soften. It is fast, warming and deeply satisfying, and it tastes like care, not like a shortcut.","ing":["Chicken breasts or thighs 500g","Chicken stock 1.5 litres","Ramen noodles 4 portions","Garlic 4 cloves, ginger 3cm piece","Soy sauce 3 tbsp, miso paste 2 tbsp","Sesame oil 1 tbsp, spring onions 4","Eggs 4, soft boiled","Chilli oil, sesame seeds and nori to serve"],"steps":["Boil the eggs for 6 and a half minutes, cool in cold water, peel, and halve them just before serving.","Heat sesame oil in a large pot, fry the garlic, ginger and the white parts of the spring onions for 2 minutes until fragrant.","Pour in the chicken stock, add soy sauce, and simmer gently for 15 minutes so the flavours come together.","Cook the chicken in the simmering broth for 12 to 15 minutes until cooked through, then lift it out, slice it, and keep it warm.","Whisk the miso with a ladle of hot broth until smooth, then stir it back into the pot. Do not boil hard after adding miso."],"tip":"Cook the noodles separately. Noodles cooked in the broth soak it up, turn the broth cloudy, and go soft before you serve."},{"id":"tacos","name":"Tacos al Pastor","cat":"world","catLabel":"World Food","country":"Mexico","veg":"nonveg","time":40,"diff":"Medium","servings":"4 people","img":"assets/tacos-al-pastor-24ef06b9.webp","shape":"tall","alt":"Tacos al pastor with marinated pork, pineapple, onion and coriander","desc":"From Mexico, tacos al pastor with chilli marinated pork, charred pineapple, onion and coriander.","intro":"Tacos al pastor began with Lebanese shawarma cooking in Mexico City, and it became something entirely Mexican, pork marinated in dried chillies and achiote, cooked until charred at the edges, and served in warm corn tortillas with pineapple, onion and coriander. The marinade does the heavy work, so give it time, even 30 minutes makes a difference, and overnight is better. Cook the pork hot and fast so it chars without drying out, warm the tortillas over an open flame or in a dry pan, and keep the toppings simple. The sweet pineapple against the smoky, spiced pork is the whole point, so do not skip it, and serve with lime and salsa on the side.","ing":["Pork shoulder 700g, thinly sliced","Dried guajillo chillies 3, ancho chilli 1","Achiote paste 2 tbsp, garlic 3 cloves","White vinegar 3 tbsp, orange juice 60ml","Cumin 1 tsp, oregano 1 tsp, salt","Pineapple 300g, cut into chunks","Corn tortillas 12, white onion 1, coriander","Limes 2, salsa of your choice"],"steps":["Soak the dried chillies in hot water for 15 minutes until soft, then drain, keeping a little of the soaking water.","Blend the chillies, achiote, garlic, vinegar, orange juice, cumin, oregano and salt into a smooth marinade, adding soaking water as needed.","Coat the pork in the marinade, cover, and refrigerate for at least 30 minutes, or overnight for the best flavour.","Heat a large pan or griddle on high heat with a little oil, and cook the pork in batches for 3 to 4 minutes per side until charred and cooked through.","In the same hot pan, sear the pineapple chunks for 1 to 2 minutes per side until golden at the edges."],"tip":"Cook in batches and do not crowd the pan. Crowded pork steams instead of charring, and you lose the crisp edges that make al pastor special."},{"id":"pozole","name":"Pozole","cat":"world","catLabel":"World Food","country":"Mexico","veg":"nonveg","time":150,"diff":"Hard","servings":"6 people","img":"assets/pozole-6cd83ab8.webp","shape":"wide","alt":"A bowl of red pozole with pork, hominy, radish, cabbage and lime","desc":"From Mexico, red pozole with slow cooked pork, hominy and a chilli broth, finished with fresh toppings.","intro":"Pozole is a celebration soup from Mexico, made with hominy, the large white corn kernels that puff and soften in a long simmer, and pork that cooks until it shreds with a spoon. The red version gets its colour and depth from dried guajillo and ancho chillies, blended smooth and stirred into the broth, while the toppings stay fresh and crisp, shredded cabbage, radish, onion, oregano and lime. It takes time, but most of that time is unattended, and the pot feeds a crowd. Cook it on a weekend, keep the broth rich and the toppings separate, and let everyone finish their own bowl at the table.","ing":["Pork shoulder 1kg, cut into large chunks","White hominy 800g, drained and rinsed","Dried guajillo chillies 4, ancho chillies 2","Onion 1, garlic 6 cloves","Bay leaves 2, oregano 2 tsp, cumin 1 tsp","Salt, water or light stock 3 litres","Shredded cabbage, radish, onion and lime to serve","Dried oregano and chilli flakes to serve"],"steps":["Soak the dried chillies in hot water for 15 minutes, drain, and blend with garlic and a little soaking water until smooth.","Put the pork, hominy, onion, bay leaves and water in a large pot, bring to a boil, and skim off any foam.","Reduce to a gentle simmer, cover partly, and cook for 90 minutes, topping up with hot water if the level falls too low.","Strain the blended chilli sauce through a sieve into the pot, stir well, and season with salt, cumin and oregano.","Simmer for 30 more minutes until the pork is tender enough to shred and the broth is rich and red."],"tip":"Strain the chilli sauce before adding it. The sieve catches skins and seeds, and the broth stays smooth and silky instead of gritty."},{"id":"padthai","name":"Pad Thai","cat":"world","catLabel":"World Food","country":"Thailand","veg":"nonveg","time":30,"diff":"Medium","servings":"4 people","img":"assets/pad-thai-c0416eb6.webp","shape":"tall","alt":"Pad thai with rice noodles, prawns, egg, peanuts and lime","desc":"From Thailand, pad thai with rice noodles, prawns, egg, a sweet sour sauce and crunchy peanuts.","intro":"Pad thai is Thailand's most famous noodle dish, and its magic is balance, sweet, sour, salty and a little heat, all in one hot wok. The sauce is made from tamarind, fish sauce, palm sugar and chilli, and it coats rice noodles that are soaked, not boiled, so they stay springy instead of soft. Prawns, egg, bean sprouts and chives go in quickly, at high heat, and the dish is finished with crushed peanuts, lime and extra sprouts on the side. Have everything ready before you start, because once the wok is hot, the cooking takes only a few minutes, and that speed is what keeps the noodles from turning mushy.","ing":["Flat rice noodles 250g","Prawns 300g, peeled","Eggs 2, lightly beaten","Tamarind paste 3 tbsp, fish sauce 3 tbsp","Palm sugar or brown sugar 3 tbsp","Garlic 3 cloves, chilli flakes 1 tsp","Bean sprouts 2 cups, garlic chives or spring onions","Roasted peanuts 4 tbsp, crushed, lime 1"],"steps":["Soak the rice noodles in warm water for 20 to 30 minutes until pliable but still firm, then drain well.","Mix the tamarind, fish sauce, sugar and chilli flakes into a sauce, and taste it. It should be sweet, sour and salty at once.","Heat oil in a wok on high heat, fry the garlic for 20 seconds, then add the prawns and cook for 2 minutes until just pink.","Push the prawns to one side, pour in the eggs, and scramble them gently until just set, then mix with the prawns.","Add the drained noodles and the sauce, and toss constantly for 2 to 3 minutes until the noodles are tender and the sauce is absorbed."],"tip":"Soak the noodles, do not boil them. Boiled noodles overcook in the wok and turn soft and sticky."},{"id":"pekingduck","name":"Peking Duck","cat":"world","catLabel":"World Food","country":"China","veg":"nonveg","time":180,"diff":"Hard","servings":"6 people","img":"assets/peking-duck-b271e564.webp","shape":"wide","alt":"A whole roast Peking duck with crisp golden skin on a platter","desc":"From China, Peking duck with crisp lacquered skin, served in thin pancakes with hoisin and spring onion.","intro":"Peking duck is one of China's great celebration dishes, famous for skin so crisp it shatters, and meat that stays juicy underneath. The secret is drying the skin and glazing it before roasting, so the fat renders out and the skin turns a deep lacquered red gold. This home version uses an overnight rest in the fridge to dry the skin, a simple maltose and vinegar glaze, and a hot oven, followed by a rest before carving. Serve it the traditional way, in thin mandarin pancakes with hoisin sauce, spring onion and cucumber, and let everyone assemble their own. It is a project, not a weeknight dinner, and it is worth every minute.","ing":["Whole duck 2 to 2.5kg","Maltose or honey 3 tbsp, rice vinegar 2 tbsp","Shaoxing wine 2 tbsp, five spice 1 tsp","Salt 1 tbsp, boiling water for blanching","Mandarin pancakes 12","Hoisin sauce 120ml","Spring onions 4, cucumber 1","Ginger and garlic for the cavity, optional"],"steps":["Clean the duck, pat it very dry, and prick the skin lightly all over with a fork, taking care not to pierce the meat.","Pour boiling water over the duck in the sink, which tightens the skin, then pat dry again.","Warm the maltose, vinegar, Shaoxing wine, five spice and salt until the maltose dissolves, and brush it all over the duck.","Rest the duck uncovered in the fridge overnight, on a rack over a tray, so the skin dries completely.","Roast breast side up at 200C for 30 minutes, then reduce to 180C and roast for 60 to 75 minutes more, until the skin is deep golden and crisp."],"tip":"Dry the skin overnight. Wet skin steams in the oven and never crisps, while dry skin renders and lacquers beautifully."},{"id":"dimsum","name":"Dim Sum","cat":"world","catLabel":"World Food","country":"China","veg":"nonveg","time":60,"diff":"Medium","servings":"4 people","img":"assets/dim-sum-ffc63fc5.webp","shape":"wide","alt":"Steamed dim sum dumplings in a bamboo steamer","desc":"From China, steamed dim sum with prawn and pork dumplings, served hot with chilli and soy dipping sauce.","intro":"Dim sum means food that touches the heart, and it is meant to be shared, small bamboo steamers arriving at the table one after another, each with a different bite inside. This home version makes two classics, prawn har gow with translucent wrappers, and pork and prawn siu mai with open tops, both steamed until just cooked and served hot. The wrappers need a light touch and a little patience, but the filling is simple, and the steaming is quick. Make them with help, one person filling, one person folding, and keep the finished dumplings covered so they do not dry out. Serve with tea, as in Cantonese yum cha, and let the meal stretch out slowly.","ing":["Prawns 300g, finely chopped","Pork mince 200g","Wheat starch 120g, tapioca starch 60g, for har gow","Wonton wrappers 20, for siu mai","Ginger 1 tbsp, grated, spring onions 2","Soy sauce 2 tbsp, sesame oil 1 tsp, white pepper","Sugar 1 tsp, Shaoxing wine 1 tbsp","Chilli oil, soy sauce and black vinegar to serve"],"steps":["Mix the prawns, pork, ginger, spring onions, soy, sesame oil, sugar, wine and white pepper into a filling, and chill for 20 minutes.","For har gow wrappers, mix wheat starch and tapioca starch with 180ml of just boiled water, knead into a smooth dough, and rest covered for 15 minutes.","Roll the har gow dough into a log, cut into small pieces, and press each one into a thin round with the side of a cleaver or a rolling pin.","Place a spoon of filling in each wrapper, fold into a crescent, and pleat the edge firmly, sealing the top.","For siu mai, place a spoon of filling in the centre of each wonton wrapper, gather the edges up around the filling, and press gently so the top stays open."],"tip":"Do not overfill the dumplings. A level teaspoon of filling seals neatly, while too much filling bursts the wrapper in the steamer."},{"id":"coqauvin","name":"Coq au Vin","cat":"world","catLabel":"World Food","country":"France","veg":"nonveg","time":120,"diff":"Hard","servings":"4 people","img":"assets/coq-au-vin-a92f118c.webp","shape":"tall","alt":"Coq au vin, chicken braised in red wine with mushrooms and pearl onions","desc":"From France, coq au vin, chicken slowly braised in red wine with mushrooms, bacon and pearl onions.","intro":"Coq au vin is classic French comfort food, chicken braised slowly in red wine until it falls from the bone, with mushrooms, pearl onions and bacon in a sauce that tastes of the wine without tasting alcoholic. It comes from Burgundy, where the wine is part of the cooking, not just an accompaniment, and the long gentle braise is what makes the chicken tender and the sauce rich. Brown the chicken well first, because that colour becomes flavour, then let the pot do the work in the oven. Serve it with mashed potatoes or crusty bread, and give the sauce a final taste for salt and a little butter to make it shine.","ing":["Chicken thighs and legs 1kg, bone in","Red wine 500ml, Burgundy style if possible","Bacon lardons 150g","Mushrooms 250g, pearl onions 12","Carrot 1, garlic 3 cloves, thyme 3 sprigs","Chicken stock 250ml, tomato paste 1 tbsp","Flour 2 tbsp, butter 2 tbsp","Parsley to serve, salt and pepper"],"steps":["Season the chicken well, dust lightly with flour, and brown it in batches in a hot ovenproof pot until deep golden on both sides. Set aside.","Fry the bacon in the same pot until crisp, lift it out, and brown the mushrooms and pearl onions in the bacon fat.","Add the carrot, garlic and tomato paste, and cook for 2 minutes, stirring, until fragrant.","Pour in the wine, scraping the bottom of the pot to lift all the browned flavour, and simmer for 3 minutes.","Return the chicken and bacon to the pot, add stock and thyme, and bring to a gentle simmer. The liquid should come halfway up the chicken."],"tip":"Brown the chicken properly before braising. Pale chicken makes a pale sauce, while deep golden chicken makes a rich, full flavoured sauce."},{"id":"bouillabaisse","name":"Bouillabaisse","cat":"world","catLabel":"World Food","country":"France","veg":"nonveg","time":75,"diff":"Hard","servings":"6 people","img":"assets/bouillabaisse-dd6562d3.webp","shape":"tall","alt":"A pot of bouillabaisse fish soup with prawns, saffron broth and herbs","desc":"From France, bouillabaisse from Marseille, a saffron fish soup with mixed seafood and rouille on toast.","intro":"Bouillabaisse comes from Marseille, where fishermen made soup from the fish that did not sell, and it is now one of France's most loved celebration dishes. The broth is the star, built from fish stock, tomatoes, fennel, orange peel, saffron and olive oil, and the fish and shellfish cook in it for only a few minutes, so they stay tender. Serve it in two parts if you can, broth strained into bowls and fish on a platter, with rouille, a saffron garlic mayonnaise, spread on toasted bread. It sounds grand, but the method is simple, make a good broth, add the fish in the right order, and do not overcook it.","ing":["Mixed firm white fish 800g, cut into chunks","Prawns 300g, mussels 300g, cleaned","Fish stock 1.5 litres","Tomatoes 400g, chopped, tomato paste 2 tbsp","Fennel 1 bulb, onion 1, leek 1","Saffron 1 large pinch, orange peel 1 strip","Garlic 4 cloves, olive oil 4 tbsp, thyme","Crusty bread, rouille, parsley and lemon to serve"],"steps":["Heat olive oil in a large pot, fry the onion, leek, fennel and garlic for 8 minutes until soft and sweet.","Add the tomato paste and chopped tomatoes, and cook for 5 minutes until the tomatoes start to break down.","Pour in the fish stock, add saffron, orange peel, thyme and a pinch of salt, and simmer for 20 minutes.","Strain the broth through a sieve, pressing the vegetables to get all the flavour, then return the broth to the pot.","Bring the broth back to a gentle simmer, and add the firmest fish first, cooking for 3 minutes."],"tip":"Do not overcook the fish. Add the firmest pieces first and the delicate pieces last, and take the pot off the heat as soon as the fish flakes."},{"id":"paella","name":"Seafood Paella","cat":"world","catLabel":"World Food","country":"Spain","veg":"nonveg","time":55,"diff":"Medium","servings":"6 people","img":"assets/seafood-paella-c85cf84d.webp","shape":"wide","alt":"Seafood paella in a wide pan with prawns, mussels, lemon and saffron rice","desc":"From Spain, seafood paella with saffron rice, prawns and mussels, and the crisp socarrat at the bottom.","intro":"Paella comes from Valencia in Spain, where it is cooked outdoors in a wide shallow pan, and the rice, not the seafood, is the real star. Saffron gives it the golden colour, a good stock gives it flavour, and the last few minutes of cooking, left undisturbed, create socarrat, the crisp toasted layer of rice at the bottom that everyone fights over. Use short grain bomba rice if you can, spread it in an even layer, and resist stirring once the stock goes in. Serve it in the pan, in the middle of the table, with lemon wedges, and let everyone dig in together.","ing":["Bomba or short grain rice 400g","Prawns 300g, mussels 300g, cleaned","Squid rings 200g, optional","Chicken or fish stock 1 litre, hot","Saffron 1 large pinch","Onion 1, red pepper 1, garlic 3 cloves","Tomatoes 2, grated, smoked paprika 1 tsp","Olive oil 4 tbsp, lemon 1, peas 100g"],"steps":["Soak the saffron in 3 tbsp of hot stock for 10 minutes, and keep the rest of the stock hot.","Heat olive oil in a wide paella pan, fry the onion and pepper for 6 minutes until soft, then add garlic and paprika.","Add the grated tomato and cook for 4 minutes until it darkens and thickens.","Add the rice and stir for 1 minute to coat it in the sofrito, then spread it in an even layer.","Pour in the hot stock and the saffron liquid, season with salt, and bring to a gentle boil. Do not stir from this point."],"tip":"Do not stir the rice after the stock goes in. Stirring releases starch and makes the rice sticky, and it stops the socarrat forming."},{"id":"beefpho","name":"Beef Pho","cat":"world","catLabel":"World Food","country":"Vietnam","veg":"nonveg","time":180,"diff":"Hard","servings":"6 people","img":"assets/beef-pho-95032754.webp","shape":"tall","alt":"A bowl of beef pho with rice noodles, sliced beef, herbs and bean sprouts","desc":"From Vietnam, beef pho with a clear spiced broth, rice noodles, thin sliced beef and fresh herbs.","intro":"Pho is Vietnam's most famous soup, and its heart is a clear broth that tastes of charred onion and ginger, star anise, cinnamon, cloves and fish sauce, simmered gently with beef bones until it is rich but never cloudy. The noodles cook separately, the beef is sliced paper thin and cooks in the hot broth as it is poured over, and the bowl is finished at the table with bean sprouts, Thai basil, coriander, lime and chilli. It takes time, but the work is mostly waiting and skimming, and the result is a bowl that is light, fragrant and deeply comforting, nothing like a heavy stew.","ing":["Beef bones 1.5kg, marrow or knuckle bones","Beef brisket or shin 500g","Rice noodles 500g, flat","Onion 2, ginger 1 large piece","Star anise 3, cinnamon stick 1, cloves 4","Coriander seeds 1 tsp, fennel seeds 1 tsp","Fish sauce 4 tbsp, rock sugar 1 tbsp","Bean sprouts, Thai basil, coriander, lime, chilli to serve"],"steps":["Blanch the bones in boiling water for 5 minutes, drain, rinse, and return them to a clean pot with fresh cold water.","Char the onion halves and ginger over an open flame or under a hot grill until blackened in patches, then add to the pot.","Toast the star anise, cinnamon, cloves, coriander and fennel in a dry pan for 2 minutes until fragrant, tie in muslin or add loose and strain later.","Simmer the broth very gently for 2 and a half hours, skimming often, and add the brisket for the last 60 minutes until tender.","Lift out the brisket, cool slightly, slice thinly, and strain the broth through a fine sieve until clear."],"tip":"Keep the simmer gentle and skim often. A rolling boil makes the broth cloudy and greasy, while a quiet simmer keeps it clear and clean tasting."},{"id":"poutine","name":"Poutine","cat":"world","catLabel":"World Food","country":"Canada","veg":"nonveg","time":45,"diff":"Easy","servings":"4 people","img":"assets/poutine-ba527eac.webp","shape":"wide","alt":"Poutine, fries topped with cheese curds and hot brown gravy","desc":"From Canada, poutine with crisp fries, squeaky cheese curds and hot beef or vegetable gravy.","intro":"Poutine comes from Quebec in Canada, and it is gloriously simple, hot crisp fries, fresh cheese curds that squeak when you bite them, and a rich brown gravy poured over the top so the curds just start to melt. The fries must be crisp enough to hold the gravy without going soggy in a minute, so double frying is worth it, and the gravy must be piping hot, because it is the heat that softens the curds. Serve it at once, in a bowl, with a fork, and eat it while the fries are still crisp at the edges and the gravy is pooling at the bottom.","ing":["Potatoes 1kg, floury variety","Cheese curds 250g, at room temperature","Beef or vegetable stock 500ml","Butter 2 tbsp, flour 2 tbsp","Soy sauce 1 tsp, Worcestershire sauce 1 tsp","Garlic 1 clove, black pepper","Oil for deep frying, salt","Spring onions to serve, optional"],"steps":["Cut the potatoes into thick batons, soak in cold water for 30 minutes, then drain and dry very well.","Heat oil to 160C, fry the chips in batches for 5 to 6 minutes until pale and soft, then drain and rest for 10 minutes.","While the chips rest, melt butter in a pan, stir in the flour, and cook for 2 minutes until lightly golden.","Whisk in the hot stock a little at a time, then add soy, Worcestershire, garlic and pepper, and simmer for 5 minutes until smooth and glossy.","Heat the oil to 190C, and fry the chips again in batches for 2 to 3 minutes until deep golden and very crisp. Drain and salt at once."],"tip":"Use cheese curds at room temperature. Cold curds stay firm and do not soften, while room temperature curds go soft and squeaky under the hot gravy."},{"id":"bobotie","name":"Bobotie","cat":"world","catLabel":"World Food","country":"South Africa","veg":"nonveg","time":75,"diff":"Medium","servings":"6 people","img":"assets/bobotie-e54f148e.webp","shape":"tall","alt":"Bobotie, a baked South African mince dish with an egg topping and bay leaves","desc":"From South Africa, bobotie with spiced mince, fruit and a golden egg topping, served with yellow rice.","intro":"Bobotie is South Africa's beloved baked mince dish, with roots in Cape Malay cooking, where spiced mince is sweetened with fruit, enriched with soaked bread, and baked under a golden egg custard topping with bay leaves. The flavour is warm and gently sweet, curry powder, turmeric, chutney, raisins and apricot all working together, and the texture is soft and comforting, somewhere between a savoury bake and a light meatloaf. Serve it with yellow rice, chutney and a simple salad, and let the sweet and savoury balance do the talking. It is an ideal make ahead dish for a crowd, because it reheats beautifully and tastes even better the next day.","ing":["Beef or lamb mince 750g","Onion 1, garlic 2 cloves, ginger 1 tsp","Curry powder 2 tbsp, turmeric 1 tsp","White bread 2 slices, milk 250ml","Eggs 3, bay leaves 4","Chutney 3 tbsp, raisins 3 tbsp","Dried apricots 4, chopped, lemon juice 1 tbsp","Almonds 2 tbsp, flaked, salt and pepper"],"steps":["Soak the bread in 125ml of the milk until soft, then squeeze out the excess milk and crumble the bread.","Fry the onion, garlic and ginger in oil for 5 minutes until soft, then add the curry powder and turmeric and fry for 1 minute.","Add the mince and fry, breaking it up, until browned all over and the liquid has cooked off.","Stir in the soaked bread, chutney, raisins, apricots, lemon juice and seasoning, and cook for 5 minutes. Taste and adjust the sweet and sour balance.","Spoon the mince into a buttered baking dish, press it down evenly, and tuck the bay leaves into the top."],"tip":"Taste the mince before baking. The sweet, sour and spicy balance must be right at this stage, because baking will not fix it."},{"id":"moussaka","name":"Moussaka","cat":"world","catLabel":"World Food","country":"Greece","veg":"nonveg","time":90,"diff":"Hard","servings":"6 people","img":"assets/moussaka-23654943.webp","shape":"square","alt":"A slice of Greek moussaka with layers of aubergine, mince and bechamel","desc":"From Greece, moussaka with layers of aubergine, spiced mince and a thick golden bechamel top.","intro":"Moussaka is Greece's great layered bake, soft aubergine, a rich tomato and lamb or beef mince sauce scented with cinnamon, and a thick bechamel top that turns golden in the oven. It takes a little time, because each layer is cooked separately before the dish is assembled, but that is what gives it its structure and flavour, and it is best made ahead and rested, so the layers set and slice cleanly. Serve it warm, in squares, with a simple salad, and do not rush the resting time. It is a Sunday dish, generous and comforting, and it feeds a table happily.","ing":["Aubergines 2 large, sliced","Potatoes 3, sliced, optional","Lamb or beef mince 600g","Onion 1, garlic 3 cloves","Tomatoes 400g, chopped, tomato paste 2 tbsp","Cinnamon 1 tsp, oregano 1 tsp, nutmeg","Milk 500ml, butter 50g, flour 50g, eggs 2","Cheese 80g, grated, kefalotyri or parmesan"],"steps":["Salt the aubergine slices and rest for 30 minutes, then pat dry and fry or roast until golden and tender. Set aside.","Boil or roast the potato slices until just tender, if using, and set aside.","Fry the onion and garlic until soft, add the mince, and brown well, breaking it up.","Add the tomato paste, chopped tomatoes, cinnamon, oregano and seasoning, and simmer for 20 minutes until thick.","Make the bechamel by melting butter, stirring in flour, and whisking in warm milk until thick and smooth. Cool slightly, then whisk in the eggs and half the cheese."],"tip":"Rest the moussaka before cutting. Hot from the oven it falls apart, rested it slices into clean, beautiful layers."},{"id":"hummus","name":"Hummus","cat":"world","catLabel":"World Food","country":"Middle East","veg":"veg","time":20,"diff":"Easy","servings":"6 people","img":"assets/hummus-7690ed83.webp","shape":"tall","alt":"A bowl of smooth hummus with olive oil, chickpeas and herbs","desc":"From the Middle East, silky smooth hummus with tahini, lemon and garlic, served with warm pitta.","intro":"Good hummus is all about texture, silky, light and whipped, never grainy or heavy. It comes from the Levant, where chickpeas, tahini, lemon and garlic are blended with ice water until the dip turns pale and fluffy, then finished with olive oil, paprika and whole chickpeas. The secret is to blend the tahini first, on its own, until it is completely smooth, and to use warm chickpeas, or chickpeas with their skins rubbed off, for the smoothest result. Serve it as part of a mezze spread, with warm pitta, olives and salad, and let everyone scoop and share.","ing":["Chickpeas 400g, cooked, drained","Tahini 120g, well stirred","Lemon juice 3 tbsp, garlic 1 small clove","Ice water 4 to 6 tbsp","Olive oil 2 tbsp, plus more to serve","Salt 1 tsp, cumin 1/2 tsp, optional","Paprika and parsley to serve","Warm pitta bread to serve"],"steps":["If using tinned chickpeas, warm them in their liquid for 5 minutes, drain, and keep a little liquid. Rub off loose skins if you have time.","Blend the tahini, lemon juice, garlic and salt for 2 minutes until very smooth, pale and slightly fluffy.","Add the warm chickpeas and blend for 3 to 4 minutes, scraping down the sides, until completely smooth.","Add ice water a tablespoon at a time, blending after each, until the hummus is light, whipped and soft enough to scoop.","Taste and adjust the lemon, salt and garlic. It should be bright and savoury, with tahini flavour, not sharp."],"tip":"Blend the tahini first, before the chickpeas. Tahini blended alone turns pale and creamy, and that is what makes the hummus silky."},{"id":"falafel","name":"Falafel","cat":"world","catLabel":"World Food","country":"Middle East","veg":"veg","time":40,"diff":"Medium","servings":"4 people","img":"assets/falafel-d3905990.webp","shape":"tall","alt":"Falafel balls with salad, pitta, tahini sauce and herbs","desc":"From the Middle East, crisp falafel made from soaked chickpeas, herbs and spices, with tahini sauce.","intro":"Real falafel is made from raw soaked chickpeas, never tinned or cooked chickpeas, and that is what gives it a light, fluffy inside and a crisp, craggy crust. The chickpeas are ground coarse with onion, garlic, parsley, coriander and cumin, rested so the mixture holds together, then shaped and fried until deep golden. Serve them in warm pitta with salad and tahini sauce, or as part of a mezze spread with hummus. The mixture can be made ahead and chilled, and the falafel fry in minutes, so they are perfect for a crowd, as long as you do not crowd the pan.","ing":["Dried chickpeas 250g, soaked overnight","Onion 1, garlic 3 cloves","Parsley 1 large bunch, coriander 1 bunch","Cumin 2 tsp, coriander powder 1 tsp","Baking powder 1/2 tsp, flour 2 tbsp","Salt 1 tsp, black pepper, chilli flakes","Oil for frying","Pitta, salad and tahini sauce to serve"],"steps":["Soak the chickpeas in plenty of cold water overnight, then drain very well. Do not cook them.","Put the chickpeas, onion, garlic, herbs, spices, salt and pepper in a food processor, and pulse until coarse and crumbly, not a paste.","Transfer to a bowl, stir in the flour and baking powder, cover, and refrigerate for 30 minutes to firm up.","Test one falafel first, shape a small ball, fry it, and check that it holds together and is cooked through.","Shape the rest into small balls or patties, about the size of a walnut, with wet hands."],"tip":"Use raw soaked chickpeas, never cooked chickpeas. Cooked chickpeas make a soft, mushy falafel that falls apart in the oil."},{"id":"feijoada","name":"Feijoada","cat":"world","catLabel":"World Food","country":"Brazil","veg":"nonveg","time":180,"diff":"Hard","servings":"8 people","img":"assets/feijoada-bb4f21f2.webp","shape":"tall","alt":"Feijoada, Brazilian black bean stew with pork in a clay pot","desc":"From Brazil, feijoada with black beans and mixed pork, served with rice, collard greens and orange.","intro":"Feijoada is Brazil's national dish, a rich black bean stew with a mix of pork, sausage and smoked meats, cooked slowly until the beans are creamy and the meats are tender. It is traditionally served on Saturdays, as a long family lunch, with white rice, sauteed collard greens, farofa, toasted cassava flour, and orange slices to cut the richness. It takes time, and it feeds a crowd, so cook a big pot, keep the accompaniments simple, and let the meal stretch out. Soak the beans overnight, brown the meats well, and give the pot a long, gentle simmer, and the result is deeply satisfying.","ing":["Dried black beans 500g, soaked overnight","Pork shoulder 500g, cubed","Smoked sausage 300g, sliced","Bacon or salt pork 200g, diced","Onion 1, garlic 4 cloves","Bay leaves 3, cumin 1 tsp, oregano 1 tsp","Orange 1, for serving, rice and collard greens","Farofa or toasted breadcrumbs to serve, optional"],"steps":["Soak the beans overnight in cold water, drain, and rinse.","Brown the pork, sausage and bacon in batches in a large pot, then set aside, keeping the fat in the pot.","Fry the onion and garlic in the same pot until soft, then add the cumin and oregano.","Return the meats to the pot, add the beans, bay leaves and enough water to cover by 3cm.","Bring to a boil, skim, then reduce to a very gentle simmer, partly covered, for 2 to 2 and a half hours."],"tip":"Soak the beans overnight and simmer gently. Rushed beans stay hard, and a hard boil breaks them into mush instead of creamy beans."},{"id":"meatpie","name":"Aussie Meat Pie","cat":"world","catLabel":"World Food","country":"Australia","veg":"nonveg","time":90,"diff":"Medium","servings":"6 people","img":"assets/aussie-meat-pie-e0439b27.webp","shape":"tall","alt":"An Australian meat pie with golden pastry, cut open to show beef filling","desc":"From Australia, the classic meat pie with rich beef filling in crisp golden pastry, served with tomato sauce.","intro":"The Aussie meat pie is an icon, handheld, golden and eaten at football games, bakeries and kitchen tables all over Australia. Inside a crisp shortcrust base and a flaky puff pastry lid is a rich beef filling, slow cooked with onion, tomato, Worcestershire sauce and a little Vegemite for depth, thick enough to hold its shape when the pie is cut, but juicy enough to need tomato sauce on top. Make the filling ahead and cool it fully, because warm filling melts the pastry, then bake until the lid is deep golden. Serve it hot, with tomato sauce, and eat it with your hands, the Australian way.","ing":["Beef chuck 700g, diced small","Onion 1, garlic 2 cloves","Tomato paste 2 tbsp, beef stock 400ml","Worcestershire sauce 2 tbsp, Vegemite 1 tsp","Flour 2 tbsp, thyme 1 tsp","Shortcrust pastry for bases, puff pastry for lids","Egg 1, beaten, for glazing","Tomato sauce to serve, salt and pepper"],"steps":["Brown the beef in batches in a hot pot, then set aside. Brown the onion and garlic in the same pot.","Add the tomato paste and flour, cook for 1 minute, then pour in the stock, stirring to lift the browned flavour.","Return the beef, add Worcestershire, Vegemite and thyme, and simmer gently for 60 to 75 minutes until tender and thick.","Cool the filling completely, in the fridge if possible. Warm filling will melt the pastry and make it soggy.","Line greased pie tins or a muffin tin with shortcrust pastry, fill with the cold beef mixture, and brush the edges with egg."],"tip":"Cool the filling completely before filling the pastry. Even slightly warm filling softens the pastry and stops it crisping in the oven."}];
